#!/usr/bin/env python3
"""Collect market data for the weekly decision round."""
import json
import math
import os
import requests
from datetime import datetime, timedelta, timezone

import market_data as yf
import fundamentals
import evidence

# For the cheap LLM filtering step
try:
    import reassess
except ImportError:
    reassess = None

# Portfolio positions + watchlist
# Read dynamic watchlist generated by scout.py
BASE = os.path.dirname(os.path.abspath(__file__))
WATCHLIST_PATH = os.path.join(BASE, "state", "watchlist.json")


def load_symbols():
    if os.path.exists(WATCHLIST_PATH):
        with open(WATCHLIST_PATH, encoding="utf-8") as handle:
            symbols = json.load(handle)
        if not isinstance(symbols, list) or any(not isinstance(s, str) for s in symbols):
            raise ValueError("Invalid watchlist")
    else:
        symbols = ['MU', 'AMD', 'ANET', 'NVDA', 'TSM', 'MRVL', 'MSFT', 'GOOGL', 'VRT', 'COHR']
    with open(os.path.join(BASE, "portfolio.json"), encoding="utf-8") as handle:
        positions = json.load(handle)["positions"]
    return sorted(set(symbols) | {p["symbol"] for p in positions})


DAY_NAMES = ['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday',
             'Sunday']



def day_name_of(value):
    """The weekday name for a date. Names live here so they are never computed by hand."""
    if value is None:
        return None
    try:
        return DAY_NAMES[value.weekday()]
    except AttributeError:
        return None


def headline(item):
    """The yfinance news schema varies by version: a flat 'title' or 'content.title'."""
    return item.get('title') or item.get('content', {}).get('title', '')


def fmp_get(endpoint, api_key, params=None):
    if not api_key:
        return None
    try:
        return yf.fmp(endpoint, **(params or {}))
    except yf.ProviderError:
        yf.event('*', endpoint, 'unavailable', 'FMP enrichment unavailable; no equivalent backup mapped')
        return None


def fred_get(series_id, api_key):
    if not api_key: return None
    url = "https://api.stlouisfed.org/fred/series/observations"
    params = {
        "series_id": series_id,
        "api_key": api_key,
        "file_type": "json",
        "sort_order": "desc",
        "limit": 1
    }
    try:
        r = requests.get(url, params=params, timeout=10)
        r.raise_for_status()
        data = r.json()
        if 'observations' in data and len(data['observations']) > 0:
            row = data['observations'][0]
            value = float(row['value'])
            return {'value': value, 'as_of': row['date'], 'source': 'FRED/'+series_id} if math.isfinite(value) else None
    except Exception:
        pass
    return None

def sector_snapshot(rows, expected_day):
    result = {}
    for row in rows or []:
        value = row.get('averageChange')
        if (row.get('date') == expected_day and row.get('sector') and
                isinstance(value, (int,float)) and not isinstance(value,bool) and math.isfinite(value)):
            key = row['sector'] + ' / ' + str(row.get('exchange') or 'unspecified exchange')
            result[key] = {'change_pct': value, 'as_of': expected_day, 'source': 'FMP sector-performance-snapshot'}
    return result or None


def main():
    SYMBOLS = load_symbols()
    results, missing_data = {}, []
    FMP_API_KEY = os.environ.get("FMP_API_KEY")
    FRED_API_KEY = os.environ.get("FRED_API_KEY")

    for symbol in SYMBOLS:
        try:
            ticker = yf.Ticker(symbol)
            # A 200-day SMA needs at least 200 trading days — 6mo (~126 days) is not enough.
            history = ticker.history(period="2y", auto_adjust=False)

            if history.empty:
                print(f"WARNING: no data for {symbol}")
                missing_data.append(f"{symbol}: no price data")
                continue

            # yfinance can return a final row that is entirely NaN (an unclosed or empty day).
            # That row made price, SMAs and returns ALL NaN through .iloc[-1], while RSI still
            # looked healthy because ewm skips NaN — the failure was silent. (See round #6.)
            history = history[history['Close'].notna()]
            if history.empty:
                print(f"WARNING: no valid close for {symbol}")
                missing_data.append(f"{symbol}: no price data (every close is NaN)")
                continue

            # The real day the price belongs to — the report's date label must rest on this.
            # The day name comes from here too: round #7 wrote "4 September, Wednesday" (a
            # Friday) and "2 September, Monday" (a Wednesday); a hand-computed day name errs.
            price_day = history.index[-1].date()
            price_date = price_day.isoformat()
            price_day_name = DAY_NAMES[price_day.weekday()]

            last_price = history['Close'].iloc[-1]

            sma50 = history['Close'].rolling(window=50).mean().iloc[-1] \
                if len(history) >= 50 else None
            sma200 = history['Close'].rolling(window=200).mean().iloc[-1] \
                if len(history) >= 200 else None

            # RSI (Wilder)
            delta = history['Close'].diff()
            gain = delta.clip(lower=0).ewm(alpha=1 / 14, adjust=False).mean()
            loss = (-delta.clip(upper=0)).ewm(alpha=1 / 14, adjust=False).mean()
            rs = gain.iloc[-1] / loss.iloc[-1] if loss.iloc[-1] else float('inf')
            rsi = 100 - (100 / (1 + rs))

            return_1m = ((history['Close'].iloc[-1] / history['Close'].iloc[-21]) - 1) * 100 \
                if len(history) >= 21 else None
            return_3m = ((history['Close'].iloc[-1] / history['Close'].iloc[-63]) - 1) * 100 \
                if len(history) >= 63 else None
            # The weekly move — the instructions' "investigate the cause" threshold (±10%)
            # reads this field.
            return_1w = ((history['Close'].iloc[-1] / history['Close'].iloc[-6]) - 1) * 100 \
                if len(history) >= 6 else None

            try:
                calendar = ticker.calendar
                earnings_date = calendar.get('Earnings Date', [None])[0] if calendar else None
            except Exception:
                earnings_date = None
            if earnings_date is None:
                missing_data.append(f"{symbol}: earnings date unavailable")

            try:
                info = ticker.info
                forward_pe = info.get('forwardPE')
                trailing_pe = info.get('trailingPE')
                market_cap = info.get('marketCap')
            except Exception:
                forward_pe, trailing_pe, market_cap = None, None, None

            try:
                news_titles = [title for title in
                               (headline(item) for item in (ticker.news or [])[:5]) if title]
            except Exception:
                news_titles = []
            if not news_titles:
                missing_data.append(f"{symbol}: no news headlines")

            def numeric(value, field, places=2):
                """NaN/Inf never reach the JSON: return None and record it as missing."""
                if value is None or not math.isfinite(float(value)):
                    missing_data.append(f"{symbol}: could not compute {field}")
                    return None
                return round(float(value), places)

            # FMP API Enrichment
            analyst_target = None
            consensus_grade = None
            insider_trades = []
            if FMP_API_KEY:
                try:
                    targets = fmp_get("price-target-summary", FMP_API_KEY, {"symbol": symbol})
                    if targets and len(targets) > 0:
                        analyst_target = targets[0].get("lastQuarterAvgPriceTarget")

                    grades = fmp_get("grades-consensus", FMP_API_KEY, {"symbol": symbol})
                    if grades and len(grades) > 0:
                        consensus_grade = grades[0].get("consensus")

                    insiders = fmp_get("insider-trading/search", FMP_API_KEY, {"symbol": symbol, "limit": 3})
                    if insiders:
                        for trade in insiders:
                            trade_type = trade.get("transactionType", "")
                            shares = trade.get("securitiesTransacted", 0)
                            person = trade.get("reportingName", "")
                            if "P-Purchase" in trade_type or "S-Sale" in trade_type:
                                insider_trades.append(f"{trade_type.split('-')[-1]} {shares} shares by {person}")
                except Exception as e:
                    print(f"FMP Warning for {symbol}: {e}")

            results[symbol] = {
                'fundamental_research': fundamentals.collect(symbol),
                'daily_returns': {str(day.date()): float(value) for day,value in history['Close'].pct_change().dropna().tail(90).items() if math.isfinite(float(value))},
                'providers': dict(ticker.providers),
                'last_price': numeric(last_price, 'price'),
                'price_date': price_date,
                'price_day_name': price_day_name,
                'sma50': numeric(sma50, 'SMA50'),
                'sma200': numeric(sma200, 'SMA200'),
                'rsi': numeric(rsi, 'RSI', 1),
                'return_1w_pct': numeric(return_1w, '1w return', 1),
                'return_1m_pct': numeric(return_1m, '1m return', 1),
                'return_3m_pct': numeric(return_3m, '3m return', 1),
                'earnings_date': str(earnings_date) if earnings_date else None,
                'earnings_day_name': day_name_of(earnings_date),
                'forward_pe': numeric(forward_pe, 'Forward PE', 2),
                'trailing_pe': numeric(trailing_pe, 'Trailing PE', 2),
                'market_cap': numeric(market_cap, 'Market Cap', 0),
                'analyst_target': numeric(analyst_target, 'Analyst Target', 2),
                'consensus_grade': consensus_grade,
                'insider_trades': insider_trades,
                'news_titles': news_titles,
            }

            if results[symbol]['last_price'] is None:
                print(f"WARNING {symbol}: could not compute the price")
            else:
                print(f"OK {symbol}: ${last_price:.2f} ({price_date})")

        except Exception as error:
            print(f"ERROR {symbol}: {error}")
            missing_data.append(f"{symbol}: {error}")

    # Date information — so the decision round never computes a day name itself.
    today = datetime.now()
    next_friday = today + timedelta(days=(4 - today.weekday()) % 7 or 7)
    next_round = today + timedelta(days=(5 - today.weekday()) % 7 or 7)

    sector_performance = None
    if FMP_API_KEY:
        today_str = yf.last_closed(datetime.now(timezone.utc)).isoformat()
        sectors = fmp_get("sector-performance-snapshot", FMP_API_KEY, {"date": today_str})
        if sectors:
            sector_performance = sector_snapshot(sectors, today_str)

    macro_data = None
    if FRED_API_KEY:
        macro_data = {
            "10-Year Treasury Yield (DGS10)": fred_get("DGS10", FRED_API_KEY),
            "Federal Funds Rate (FEDFUNDS)": fred_get("FEDFUNDS", FRED_API_KEY)
        }

    if not sector_performance:
        missing_data.append('Sector performance unavailable')
    if not macro_data or any(value is None for value in macro_data.values()):
        missing_data.append('One or more macro observations unavailable')

    results['_meta'] = {
        'date': today.strftime('%Y-%m-%d'),
        'collected_at': datetime.now(timezone.utc).isoformat(),
        'day_name': DAY_NAMES[today.weekday()],
        'next_friday': f"{next_friday.strftime('%Y-%m-%d')} (Friday — the weekly close)",
        'next_round': f"{next_round.strftime('%Y-%m-%d')} (Saturday — the next decision round)",
        'symbol_count': f"{len(results)}/{len(SYMBOLS)}",
        'missing_data': missing_data,
        'sector_performance': sector_performance,
        'macro_data': macro_data,
    }

    source_facts = evidence.ledger(results, results['_meta']['collected_at'], 'weekly_data/market_data')

    # --- MULTI-AGENT RESEARCH TEAM (FinThink / TradingAgents Architecture) ---
    api_key = os.environ.get("OPENROUTER_API_KEY")

    if api_key and reassess:
        print("\nDeploying Multi-Agent Research Team (Isolating Contexts)...")

        # Dynamic Auto-Discovery: Find the absolute newest models available on OpenRouter
        macro_model = (os.environ.get("OPENROUTER_MODEL_MACRO") or "openai/gpt-4o")
        fund_model = (os.environ.get("OPENROUTER_MODEL_FUNDAMENTAL") or "anthropic/claude-sonnet-5")
        sent_model = (os.environ.get("OPENROUTER_MODEL_SENTIMENT") or "google/gemini-3.5-flash")

        results['_meta']['research_models'] = {'macro':macro_model, 'fundamental':fund_model, 'sentiment':sent_model}

        # 1. Macro Analyst Agent
        macro_data_only = {
            "macro_data": results.get('_meta', {}).get('macro_data'),
            "sector_performance": results.get('_meta', {}).get('sector_performance')
        }
        macro_sys = (
            "You are the Chief Macro Strategist. Analyze these interest rates, yields, and sector performances. "
            "Provide a 2-3 sentence global macroeconomic outlook on how this environment affects the tech/semiconductor sector. "
            "Return ONLY a JSON object with a single key 'macro_environment' mapping to your outlook string."
        )
        macro_payload, macro_status = reassess.call_llm(macro_model, macro_sys, json.dumps(macro_data_only), api_key)
        global_macro_outlook = macro_payload.get('macro_environment', '') if isinstance(macro_payload, dict) else str(macro_payload)

        # Prepare stripped-down datasets for the other two agents
        fundamental_data = {}
        sentiment_data = {}
        for sym, data in results.items():
            if sym == '_meta': continue
            fundamental_data[sym] = {
                "last_price": data.get("last_price"),
                "forward_pe": data.get("forward_pe"),
                "trailing_pe": data.get("trailing_pe"),
                "market_cap": data.get("market_cap"),
                "insider_trades": data.get("insider_trades"),
                "financial_statements": data.get("fundamental_research")
            }
            sentiment_data[sym] = {
                "analyst_target": data.get("analyst_target"),
                "consensus_grade": data.get("consensus_grade"),
                "news_titles": data.get("news_titles")
            }

        # 2. Fundamental Analyst Agent
        fund_sys = (
            "You are a fundamental research analyst. Assess revenue growth, margins, cash conversion, "
            "debt, liquidity, valuation and insider evidence from the supplied dated statements. "
            "Distinguish missing evidence from weakness. Do not invent guidance or filing footnotes. "
            "Return a JSON object keyed by ticker. Each value must contain nonempty strings: "
            "summary, bull_case, bear_case, invalidation, data_gaps. Explain the strongest "
            "counterargument and what would falsify the thesis. Use only SOURCE_LEDGER references "
            "for numeric facts; do not claim access to filings that were not supplied."
        )
        def validate_research(payload):
            if not isinstance(payload, dict) or set(payload) != set(fundamental_data):
                raise ValueError('Research must cover every supplied company')
            for report in payload.values():
                if not isinstance(report, dict) or set(report) != {'summary','bull_case','bear_case','invalidation','data_gaps'}:
                    raise ValueError('Missing research or counterargument fields')
                if any(not isinstance(t,str) or not t.strip() for t in report.values()):
                    raise ValueError('Empty fundamental research field')
        fund_payload, fund_status = reassess.call_llm(fund_model, fund_sys, json.dumps(fundamental_data), api_key,
                                                     source_ledger=source_facts, response_validator=validate_research)

        # 3. Sentiment & News Analyst Agent
        sent_sys = (
            "You are a Sentiment and News Analyst. You ONLY look at news headlines and Wall Street analyst targets/grades. "
            "For each ticker, output a 1-sentence sentiment analysis based on the narrative and targets. "
            "Return ONLY a JSON object mapping each ticker to its 1-sentence sentiment analysis."
        )
        sent_payload, sent_status = reassess.call_llm(sent_model, sent_sys, json.dumps(sentiment_data), api_key)

        # Combine outputs into the Research Dossier
        for symbol in SYMBOLS:
            if symbol not in results: continue
            f_thesis = fund_payload.get(symbol, "N/A") if isinstance(fund_payload, dict) else "N/A"
            s_thesis = sent_payload.get(symbol, "N/A") if isinstance(sent_payload, dict) else "N/A"

            results[symbol]['research_team_dossier'] = {
                "macro_environment": global_macro_outlook,
                "fundamental_thesis": f_thesis,
                "sentiment_news": s_thesis
            }

        failures = []
        if macro_status != "ok" or not isinstance(macro_payload, dict) or not macro_payload.get("macro_environment"):
            failures.append("macro analyst")
        for role, payload, status in (("fundamental analyst", fund_payload, fund_status),
                                      ("sentiment analyst", sent_payload, sent_status)):
            if status != "ok" or not isinstance(payload, dict) or any(
                    not payload.get(symbol) or (role == 'sentiment analyst' and not isinstance(payload.get(symbol), str))
                    for symbol in results if not symbol.startswith("_")):
                failures.append(role)
        results['_meta']['research_errors'] = failures
        print("Research incomplete: " + ", ".join(failures) if failures else
              "Successfully compiled Multi-Agent Research Dossiers.")
    else:
        print("No OPENROUTER_API_KEY found, skipping multi-agent research.")

    with open(os.path.join(BASE, 'weekly_data.json'), 'w', encoding='utf-8') as handle:
        json.dump(results, handle, indent=2, ensure_ascii=False, allow_nan=False)

    print(f"\nCollected data for {len(results) - 1}/{len(SYMBOLS)} symbols")
    if missing_data:
        print(f"MISSING DATA ({len(missing_data)} entries):")
        for item in missing_data:
            print(f"  - {item}")
    print(f"Date: {today.strftime('%Y-%m-%d %H:%M:%S')} ({DAY_NAMES[today.weekday()]})")

    if results['_meta'].get('research_errors'):
        raise RuntimeError("Research team incomplete; inspect weekly_data.json metadata")


if __name__ == "__main__":
    main()
